        private static void Project(Window owner, DeepSystemsContext ctx, string civilization, object source, string sourceId, string rule)
        {
            if (ctx == null || source == null) return; ExpeditionWorkspace.Visit(ctx, "documents", civilization + " projection", rule); Ensure(ctx); string fp = HashObject(source); string sid = String.IsNullOrWhiteSpace(sourceId) ? "UNKNOWN" : sourceId;
            LivingProjectionReceipt prior = Store.Projections.FirstOrDefault(x => String.Equals(x.Civilization, civilization, StringComparison.OrdinalIgnoreCase) && String.Equals(x.SourceId, sid, StringComparison.OrdinalIgnoreCase));
            LivingProjectionReceipt r = new LivingProjectionReceipt { Id = LivingDocumentKernel.NewId("PROJ"), Civilization = civilization, SourceId = sid, SourceFingerprint = fp, Rule = rule }; r.CertificateHash = LivingDocumentKernel.HashText(r.Civilization + "|" + r.SourceId + "|" + r.SourceFingerprint + "|" + r.Rule); Store.Projections.Insert(0, r); Trim(Store.Projections, 4096);
            int stale = 0; if (prior != null && !String.Equals(prior.SourceFingerprint, fp, StringComparison.OrdinalIgnoreCase)) stale = PropagateSourceRevision(civilization, sid, prior.SourceFingerprint, fp);
            Save(ctx); AppendLedger(ctx, "PROJECTION", sid, civilization + " → DOCΩ" + (stale > 0 ? "; " + stale + " paragraphs marked stale in new versions" : ""), "", r.CertificateHash); Open(owner, ctx);
        }

        private static int PropagateSourceRevision(string civilization, string sourceId, string oldFp, string newFp)
        {
            int total = 0; foreach (LivingDocument d in Store.Documents.ToList()) { LivingVersion current = LivingDocumentKernel.Current(d); if (current == null) continue; bool references = current.Evidence.Any(x => String.Equals(x.SourceCivilization, civilization, StringComparison.OrdinalIgnoreCase) && String.Equals(x.SourceId, sourceId, StringComparison.OrdinalIgnoreCase) && String.Equals(x.SourceFingerprint, oldFp, StringComparison.OrdinalIgnoreCase)); if (!references) continue; LivingVersion next = CloneVersion(d, current, "Upstream source fingerprint changed: " + civilization + "/" + sourceId, current.Branch); int changed = LivingDocumentKernel.MarkSourceFingerprintChanged(next, civilization, sourceId, oldFp, newFp); if (changed > 0) { CommitVersion(d, next); total += changed; } }
            return total;
        }

        private static void OpenDocuments(Window owner, DeepSystemsContext ctx)
        {
            Ensure(ctx); Window w = W(owner, "YOMI · LIVING DOCUMENT REGISTRY", 1420, 860); DockPanel root = Shell("LIVING DOCUMENT REGISTRY", "Double-click a document to inspect its current version and complete lineage."); ListBox list = List(); list.ItemsSource = Store.Documents; list.MouseDoubleClick += delegate { LivingDocument d = list.SelectedItem as LivingDocument; if (d != null) OpenDocument(w, ctx, d); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void OpenDocument(Window owner, DeepSystemsContext ctx, LivingDocument d)
        {
            LivingVersion v = LivingDocumentKernel.Current(d); if (v == null) return; Window w = W(owner, "YOMI · DOCΩ · " + d.Title, 1480, 900); DockPanel root = Shell(d.Title, (d.Kind ?? "DOCUMENT") + "   ·   " + (d.Objective ?? "")); TextBlock meta = new TextBlock { Text = "document " + d.Id + "   ·   current v" + v.Number + "   ·   " + v.Branch + "   ·   fp " + LivingDocumentKernel.Short(v.RootFingerprint) + "   ·   " + v.Paragraphs.Count + " paragraphs   ·   " + v.Claims.Count + " claims   ·   " + v.Evidence.Count + " evidence anchors", Foreground = Accent, Margin = new Thickness(20, 0, 20, 10), TextWrapping = TextWrapping.Wrap }; DockPanel.SetDock(meta, Dock.Top); root.Children.Add(meta); WrapPanel p = new WrapPanel { Margin = new Thickness(14) };
            SmallPortal(p, "PARAGRAPHS", delegate { OpenCollection(w, "PARAGRAPHS · " + d.Title, v.Paragraphs.Cast<object>().ToList(), "Visible prose surface."); }); SmallPortal(p, "CLAIMS", delegate { OpenCollection(w, "CLAIMS · " + d.Title, v.Claims.Cast<object>().ToList(), "Explicit proposition graph."); }); SmallPortal(p, "EVIDENCE", delegate { OpenCollection(w, "EVIDENCE · " + d.Title, v.Evidence.Cast<object>().ToList(), "Content-addressed source spine."); }); SmallPortal(p, "VERSIONS", delegate { OpenCollection(w, "VERSIONS · " + d.Title, d.Versions.OrderByDescending(x => x.Number).Cast<object>().ToList(), "Immutable history."); }); SmallPortal(p, "VALIDATE", delegate { OpenCollection(w, "VALIDATION · " + d.Title, LivingDocumentKernel.Validate(v).Cast<object>().ToList(), "Current graph integrity."); }); SmallPortal(p, "RENDER", delegate { TextView(w, "CANONICAL RENDER · " + d.Title, LivingDocumentKernel.RenderMarkdown(d, v)); }); SmallPortal(p, "WORLD SPINE", delegate { WorldPassportSpine.CaptureAndOpen(w, ctx, d.Title + " · v" + v.Number.ToString(CultureInfo.InvariantCulture), "LIVING_DOCUMENT_VERSION", "DOCΩ", "documents", v.Id, v, "", "$document/" + d.Id + "/version/" + v.Id); });
            root.Children.Add(new ScrollViewer { Content = p, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }); w.Content = root; w.Show();
        }

        private static void NewDocument(Window owner, DeepSystemsContext ctx)
        {
            string title = Prompt(owner, "NEW INTELLIGENCE WORK", "Document title:", "Untitled intelligence dossier"); if (title == null) return; string kind = Prompt(owner, "DOCUMENT KIND", "REPORT, MANUAL, RESEARCH_DOSSIER or SPECIFICATION:", "RESEARCH_DOSSIER"); if (kind == null) return; LivingDocument d = LivingDocumentKernel.Starter(title, kind); Store.Documents.Insert(0, d); Trim(Store.Documents, MaxDocuments); Save(ctx); LivingVersion v = LivingDocumentKernel.Current(d); AppendLedger(ctx, "DOCUMENT_GENESIS", d.Id, d.Title + " · " + d.Kind, v == null ? "" : v.RootFingerprint, ""); OpenDocument(owner, ctx, d);
        }

        private static void AddParagraph(Window owner, DeepSystemsContext ctx)
        {
            LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null || cur.Frozen) { MessageBox.Show(owner, "The active version is frozen. Fork/checkpoint first.", "YOMI · DOCΩ", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            string heading = Prompt(owner, "PARAGRAPH FORGE", "Paragraph heading:", "New finding"); if (heading == null) return; string text = Prompt(owner, "PARAGRAPH FORGE", "Paragraph text:", ""); if (text == null) return; LivingVersion next = CloneVersion(d, cur, "Add paragraph: " + heading, cur.Branch); LivingParagraph p = new LivingParagraph { Id = LivingDocumentKernel.NewId("PARA"), Heading = heading, Text = text, Role = "BODY" };
            if (next.Evidence.Count > 0) p.EvidenceIds.Add(next.Evidence[0].Id); LivingClaim c = new LivingClaim { Id = LivingDocumentKernel.NewId("CLAIM"), Text = text, Kind = "ASSERTION", Confidence = next.Evidence.Count > 0 ? 0.65 : 0.35 }; if (next.Evidence.Count > 0) c.EvidenceIds.Add(next.Evidence[0].Id); c.CertificateHash = LivingDocumentKernel.FingerprintClaim(c); next.Claims.Add(c); p.ClaimIds.Add(c.Id); p.CertificateHash = LivingDocumentKernel.FingerprintParagraph(p); next.Paragraphs.Add(p); LivingSection s = next.Sections.OrderBy(x => x.Order).LastOrDefault(); if (s == null) { s = new LivingSection { Id = LivingDocumentKernel.NewId("SEC"), Title = "Body", Order = 1 }; next.Sections.Add(s); } s.ParagraphIds.Add(p.Id); next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "PARAGRAPH_ADD", p.Id, d.Title + " v" + next.Number + " · " + heading, next.RootFingerprint, p.CertificateHash); OpenDocument(owner, ctx, d);
        }

        private static void BindProjection(Window owner, DeepSystemsContext ctx)
        {
            LivingDocument d = ChooseDocument(owner); if (d == null || Store.Projections.Count == 0) return; LivingProjectionReceipt r = Choose<LivingProjectionReceipt>(owner, "Choose source projection", Store.Projections); if (r == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null || cur.Frozen) return; LivingVersion next = CloneVersion(d, cur, "Bind source projection " + r.Civilization + "/" + r.SourceId, cur.Branch); LivingEvidenceAnchor e = new LivingEvidenceAnchor { Id = LivingDocumentKernel.NewId("EVID"), SourceCivilization = r.Civilization, SourceId = r.SourceId, SourceFingerprint = r.SourceFingerprint, Locator = "projection://" + r.Civilization + "/" + r.SourceId, Label = r.Civilization + " · " + r.SourceId, Excerpt = r.Rule, Authority = "UPSTREAM_PROJECTION", Confidence = 1.0 }; e.CertificateHash = LivingDocumentKernel.HashText(e.Id + "|" + e.SourceCivilization + "|" + e.SourceId + "|" + e.SourceFingerprint + "|" + e.Excerpt); next.Evidence.Insert(0, e); next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "EVIDENCE_BIND", e.Id, d.Title + " ← " + r.Civilization + "/" + r.SourceId, next.RootFingerprint, e.CertificateHash); OpenCollection(owner, "SOURCE BOUND", new List<object> { e }, "A new document version now contains the fingerprinted source anchor.");
        }

        private static void AddCalculation(Window owner, DeepSystemsContext ctx)
        {
            LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null || cur.Frozen) return; string name = Prompt(owner, "CALCULATION", "Name:", "Derived measure"); if (name == null) return; string expression = Prompt(owner, "CALCULATION", "Expression (retained text; not executed):", "a / b"); if (expression == null) return; string output = Prompt(owner, "CALCULATION", "Recorded output:", ""); if (output == null) return; LivingVersion next = CloneVersion(d, cur, "Add calculation: " + name, cur.Branch); LivingCalculation c = new LivingCalculation { Id = LivingDocumentKernel.NewId("CALC"), Name = name, Expression = expression, Output = output, Explanation = "User-recorded calculation artifact. DOCΩ retains lineage but does not execute arbitrary expressions." }; if (next.Evidence.Count > 0) c.EvidenceIds.Add(next.Evidence[0].Id); c.CertificateHash = LivingDocumentKernel.HashText(c.Id + "|" + c.Name + "|" + c.Expression + "|" + c.Output + "|" + String.Join(",", c.EvidenceIds.ToArray())); next.Calculations.Insert(0, c); next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "CALCULATION_ADD", c.Id, d.Title + " · " + c.Name, next.RootFingerprint, c.CertificateHash); OpenCollection(owner, "CALCULATION CREATED", new List<object> { c }, "Expression is retained as evidence; arbitrary code is never evaluated.");
        }

