        private static void AddObjection(Window owner, DeepSystemsContext ctx)
        {
            LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null || cur.Claims.Count == 0 || cur.Frozen) return; LivingClaim selected = Choose<LivingClaim>(owner, "Choose challenged claim", cur.Claims); if (selected == null) return; string text = Prompt(owner, "OBJECTION", "Strongest objection/counterargument:", ""); if (text == null) return; LivingVersion next = CloneVersion(d, cur, "Add objection to " + selected.Id, cur.Branch); LivingClaim c = next.Claims.First(x => x.Id == selected.Id); LivingObjection o = new LivingObjection { Id = LivingDocumentKernel.NewId("OBJ"), TargetClaimId = c.Id, Position = text, Severity = "MATERIAL", Status = "OPEN" }; if (next.Evidence.Count > 0) o.EvidenceIds.Add(next.Evidence[0].Id); o.CertificateHash = LivingDocumentKernel.HashText(o.Id + "|" + o.TargetClaimId + "|" + o.Position + "|" + String.Join(",", o.EvidenceIds.ToArray())); next.Objections.Insert(0, o); if (!c.ObjectionIds.Contains(o.Id)) c.ObjectionIds.Add(o.Id); c.CertificateHash = LivingDocumentKernel.FingerprintClaim(c); next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "OBJECTION_ADD", o.Id, "claim " + c.Id, next.RootFingerprint, o.CertificateHash);
        }

