            LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null || cur.Frozen) return; string title = Prompt(owner, "DECISION RECORD", "Decision title:", "Decision"); if (title == null) return; string decision = Prompt(owner, "DECISION RECORD", "Decision:", ""); if (decision == null) return; LivingVersion next = CloneVersion(d, cur, "Add decision record: " + title, cur.Branch); LivingDecisionRecord a = new LivingDecisionRecord { Id = LivingDocumentKernel.NewId("ADR"), Title = title, Decision = decision }; if (next.Claims.Count > 0) a.ClaimIds.Add(next.Claims[0].Id); if (next.Evidence.Count > 0) a.EvidenceIds.Add(next.Evidence[0].Id); a.CertificateHash = LivingDocumentKernel.HashText(a.Id + "|" + a.Title + "|" + a.Decision + "|" + String.Join(",", a.ClaimIds.ToArray())); next.Decisions.Insert(0, a); next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "DECISION_ADD", a.Id, a.Title, next.RootFingerprint, a.CertificateHash);
