        private static void ParagraphMicroscope(Window owner)
        {
            WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { LivingParagraph p = Choose<LivingParagraph>(owner, "Choose paragraph", v.Paragraphs); if (p == null) return; List<object> rows = new List<object> { p }; rows.AddRange(v.Claims.Where(x => p.ClaimIds.Contains(x.Id)).Cast<object>()); rows.AddRange(v.Evidence.Where(x => p.EvidenceIds.Contains(x.Id) || v.Claims.Where(c => p.ClaimIds.Contains(c.Id)).Any(c => c.EvidenceIds.Contains(x.Id))).Cast<object>()); rows.AddRange(v.Calculations.Where(x => p.CalculationIds.Contains(x.Id) || v.Claims.Where(c => p.ClaimIds.Contains(c.Id)).Any(c => c.CalculationIds.Contains(x.Id))).Cast<object>()); rows.AddRange(v.Models.Where(x => p.ModelIds.Contains(x.Id) || v.Claims.Where(c => p.ClaimIds.Contains(c.Id)).Any(c => c.ModelIds.Contains(x.Id))).Cast<object>()); rows.AddRange(v.Objections.Where(x => p.ObjectionIds.Contains(x.Id) || v.Claims.Where(c => p.ClaimIds.Contains(c.Id)).Any(c => c.ObjectionIds.Contains(x.Id))).Cast<object>()); OpenCollection(owner, "PARAGRAPH MICROSCOPE · " + p.Heading, rows, "Visible prose first, then every retained dependency beneath it."); });
        }

        private static void DependencyConstellation(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { List<object> rows = new List<object>(); foreach (LivingParagraph p in v.Paragraphs) foreach (string dep in p.DependsOnParagraphIds) rows.Add(p.Id + "   →   " + dep + "   ·   " + p.Heading); OpenCollection(owner, "PARAGRAPH DEPENDENCIES · " + d.Title, rows, "Explicit dependency edges only."); }); }
        private static void StalenessView(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { OpenCollection(owner, "STALE PARAGRAPHS · " + d.Title, v.Paragraphs.Where(x => x.Stale).Cast<object>().ToList(), "Staleness is propagated from changed bound source fingerprints and explicit paragraph dependencies."); }); }
        private static void SourceRevisionRadar(Window owner) { List<object> rows = new List<object>(); foreach (IGrouping<string,LivingProjectionReceipt> g in Store.Projections.GroupBy(x => (x.Civilization ?? "") + "|" + (x.SourceId ?? ""), StringComparer.OrdinalIgnoreCase)) { List<LivingProjectionReceipt> xs = g.OrderByDescending(x => x.CreatedUtc).ToList(); if (xs.Select(x => x.SourceFingerprint).Distinct(StringComparer.OrdinalIgnoreCase).Count() > 1) rows.Add(g.Key + "   ·   " + xs.Count + " projections   ·   " + xs.Select(x => LivingDocumentKernel.Short(x.SourceFingerprint)).Distinct().Count() + " fingerprints"); } OpenCollection(owner, "SOURCE REVISION RADAR", rows, "Repeated source identity with changed fingerprints is a first-class change signal."); }

