        {
            WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { if (v.Evidence.Count == 0) return; LivingEvidenceAnchor e = Choose<LivingEvidenceAnchor>(owner, "Choose evidence source", v.Evidence); if (e == null) return; LivingImpactReport r = LivingDocumentKernel.Impact(v, "EVIDENCE", e.Id); Store.Impacts.Insert(0, r); Trim(Store.Impacts, 4096); Save(ctx); AppendLedger(ctx, "IMPACT", r.Id, d.Title + " · evidence " + e.Id, v.RootFingerprint, r.CertificateHash); List<object> rows = new List<object> { r }; rows.AddRange(r.Claims.Cast<object>()); rows.AddRange(r.Paragraphs.Cast<object>()); rows.AddRange(r.Reasons.Cast<object>()); OpenCollection(owner, "CHANGE IMPACT · " + e.Label, rows, "Exact explicit dependency cone."); });
        }

