        private static void OrphanEvidence(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { HashSet<string> used = new HashSet<string>(v.Paragraphs.SelectMany(x => x.EvidenceIds).Concat(v.Claims.SelectMany(x => x.EvidenceIds)).Concat(v.Calculations.SelectMany(x => x.EvidenceIds)).Concat(v.Assumptions.SelectMany(x => x.EvidenceIds)).Concat(v.Objections.SelectMany(x => x.EvidenceIds)).Concat(v.Requirements.SelectMany(x => x.EvidenceIds)), StringComparer.Ordinal); OpenCollection(owner, "ORPHAN EVIDENCE · " + d.Title, v.Evidence.Where(x => !used.Contains(x.Id)).Cast<object>().ToList(), "Unused evidence is not deleted automatically."); }); }
