        private static void VersionDiff(Window owner) { LivingDocument d = ChooseDocument(owner); if (d == null || d.Versions.Count < 2) return; LivingVersion a = Choose<LivingVersion>(owner, "Choose earlier version", d.Versions.OrderBy(x => x.Number).ToList()); if (a == null) return; LivingVersion b = Choose<LivingVersion>(owner, "Choose later version", d.Versions.OrderBy(x => x.Number).ToList()); if (b == null) return; LivingVersionDiff diff = LivingDocumentKernel.Diff(a, b); List<object> rows = new List<object> { diff }; rows.AddRange(diff.AddedParagraphs.Select(x => (object)("+ PARAGRAPH " + x))); rows.AddRange(diff.RemovedParagraphs.Select(x => (object)("- PARAGRAPH " + x))); rows.AddRange(diff.ChangedParagraphs.Select(x => (object)("~ PARAGRAPH " + x))); rows.AddRange(diff.AddedClaims.Select(x => (object)("+ CLAIM " + x))); rows.AddRange(diff.RemovedClaims.Select(x => (object)("- CLAIM " + x))); rows.AddRange(diff.ChangedClaims.Select(x => (object)("~ CLAIM " + x))); OpenCollection(owner, "VERSION DIFF · " + d.Title, rows, "Identity-aware graph diff."); }

