        private static void Baseline(Window owner, DeepSystemsContext ctx) { LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion v = LivingDocumentKernel.Current(d); if (v == null) return; LivingBaseline b = new LivingBaseline { Id = LivingDocumentKernel.NewId("BASE"), DocumentId = d.Id, VersionId = v.Id, VersionFingerprint = v.RootFingerprint, Name = d.Title + " · v" + v.Number, CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }; b.CertificateHash = LivingDocumentKernel.HashText(b.DocumentId + "|" + b.VersionId + "|" + b.VersionFingerprint + "|" + b.Name); Store.Baselines.Insert(0, b); Trim(Store.Baselines, 2048); Save(ctx); AppendLedger(ctx, "BASELINE", b.Id, b.Name, v.RootFingerprint, b.CertificateHash); OpenCollection(owner, "BASELINE CREATED", new List<object> { b }, "Immutable comparison anchor."); }
        private static void FreezeVersion(Window owner, DeepSystemsContext ctx) { LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion cur = LivingDocumentKernel.Current(d); if (cur == null) return; List<LivingValidationFinding> findings = LivingDocumentKernel.Validate(cur); int errors = findings.Count(x => String.Equals(x.Severity, "ERROR", StringComparison.OrdinalIgnoreCase)); if (errors > 0) { OpenCollection(owner, "FREEZE REFUSED · VALIDATION ERRORS", findings.Cast<object>().ToList(), "Resolve structural errors before publication freeze."); return; } if (cur.Frozen) return; LivingVersion next = CloneVersion(d, cur, "Publication freeze", cur.Branch); next.Frozen = true; next.RootFingerprint = LivingDocumentKernel.Fingerprint(next); CommitVersion(d, next); Save(ctx); AppendLedger(ctx, "FREEZE", next.Id, d.Title + " v" + next.Number, next.RootFingerprint, ""); }
        private static void SealPublication(Window owner, DeepSystemsContext ctx) { LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion v = LivingDocumentKernel.Current(d); if (v == null) return; List<LivingValidationFinding> findings = LivingDocumentKernel.Validate(v); int errors = findings.Count(x => String.Equals(x.Severity, "ERROR", StringComparison.OrdinalIgnoreCase)); int warnings = findings.Count(x => String.Equals(x.Severity, "WARN", StringComparison.OrdinalIgnoreCase)); if (errors > 0) { OpenCollection(owner, "SEAL REFUSED", findings.Cast<object>().ToList(), "Publication seal requires zero structural errors."); return; } string rendered = LivingDocumentKernel.RenderMarkdown(d, v); LivingPublicationSeal s = new LivingPublicationSeal { Id = LivingDocumentKernel.NewId("SEAL"), DocumentId = d.Id, VersionId = v.Id, VersionFingerprint = v.RootFingerprint, RenderedFingerprint = LivingDocumentKernel.HashText(rendered), WarningCount = warnings, ErrorCount = errors, CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }; s.CertificateHash = LivingDocumentKernel.HashText(s.DocumentId + "|" + s.VersionId + "|" + s.VersionFingerprint + "|" + s.RenderedFingerprint + "|" + s.WarningCount + "|" + s.ErrorCount); Store.Seals.Insert(0, s); Trim(Store.Seals, 2048); Save(ctx); AppendLedger(ctx, "PUBLICATION_SEAL", s.Id, d.Title + " v" + v.Number, v.RootFingerprint, s.CertificateHash); OpenCollection(owner, "PUBLICATION SEALED", new List<object> { s }, "Graph fingerprint and rendered artifact fingerprint are bound together."); }

        private static void RenderPreview(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { TextView(owner, "CANONICAL RENDER · " + d.Title, LivingDocumentKernel.RenderMarkdown(d, v)); }); }
        private static void ExportPackage(Window owner, DeepSystemsContext ctx)
        {
            LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion v = LivingDocumentKernel.Current(d); if (v == null) return; string root = Path.Combine(ctx.DataRoot, "deep-systems", "living-document-exports"); Directory.CreateDirectory(root); string stem = SafeName(d.Title) + "-v" + v.Number + "-" + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture); string md = Path.Combine(root, stem + ".md"), manifest = Path.Combine(root, stem + ".manifest.json"); string rendered = LivingDocumentKernel.RenderMarkdown(d, v); File.WriteAllText(md, rendered, new UTF8Encoding(false)); var m = new { schema = 1, product = "YOMI", civilization = "DEV13.37.26", document_id = d.Id, version_id = v.Id, version = v.Number, branch = v.Branch, version_fingerprint = v.RootFingerprint, rendered_sha256 = LivingDocumentKernel.HashText(rendered), source_fingerprints = v.Evidence.Select(x => new { civilization = x.SourceCivilization, source_id = x.SourceId, fingerprint = x.SourceFingerprint, certificate = x.CertificateHash }).ToList(), validation = LivingDocumentKernel.Validate(v).Select(x => new { severity = x.Severity, kind = x.Kind, subject = x.SubjectId, message = x.Message }).ToList() }; File.WriteAllText(manifest, Json.Serialize(m), new UTF8Encoding(false)); AppendLedger(ctx, "EXPORT_PACKAGE", v.Id, md, v.RootFingerprint, LivingDocumentKernel.HashText(File.ReadAllText(manifest, Encoding.UTF8))); try { Clipboard.SetText(md + Environment.NewLine + manifest); } catch { } MessageBox.Show(owner, "Publication package written inside YOMI data and both paths copied to the clipboard.\n\n" + md + "\n" + manifest, "YOMI · DOCΩ Export", MessageBoxButton.OK, MessageBoxImage.Information);
        }

