        private static void ReproducibilityCapsule(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { List<object> rows = new List<object> { "DOCUMENT " + d.Id, "VERSION " + v.Id, "ROOT " + v.RootFingerprint, "RENDER " + LivingDocumentKernel.HashText(LivingDocumentKernel.RenderMarkdown(d, v)) }; rows.AddRange(v.Evidence.Select(x => (object)("SOURCE " + x.SourceCivilization + "/" + x.SourceId + " " + x.SourceFingerprint))); rows.AddRange(v.Calculations.Cast<object>()); rows.AddRange(v.Models.Cast<object>()); rows.AddRange(LivingDocumentKernel.Validate(v).Cast<object>()); OpenCollection(owner, "REPRODUCIBILITY CAPSULE · " + d.Title, rows, "Everything needed to reconstruct the review surface from retained graph state."); }); }
