        private static void CalculationLineage(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { List<object> rows = new List<object>(); foreach (LivingCalculation c in v.Calculations) { rows.Add(c); rows.AddRange(v.Evidence.Where(x => c.EvidenceIds.Contains(x.Id)).Cast<object>()); rows.AddRange(v.Claims.Where(x => x.CalculationIds.Contains(c.Id)).Cast<object>()); rows.AddRange(v.Paragraphs.Where(x => x.CalculationIds.Contains(c.Id) || v.Claims.Where(q => q.CalculationIds.Contains(c.Id)).Any(q => x.ClaimIds.Contains(q.Id))).Cast<object>()); } OpenCollection(owner, "CALCULATION LINEAGE · " + d.Title, rows, "Arithmetic artifact to prose consequence."); }); }
        private static void ModelLimitationRadar(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { OpenCollection(owner, "MODEL LIMITATION RADAR · " + d.Title, v.Models.Where(x => x.Limitations == null || x.Limitations.Count < 1).Cast<object>().ToList(), "A model without retained limitations is publication risk."); }); }
        private static void RequirementCrosswalk(Window owner) { WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { List<object> rows = new List<object>(); foreach (LivingRequirement q in v.Requirements) { rows.Add(q); rows.AddRange(v.Claims.Where(x => q.ClaimIds.Contains(x.Id)).Cast<object>()); rows.AddRange(v.Evidence.Where(x => q.EvidenceIds.Contains(x.Id)).Cast<object>()); rows.AddRange(q.VerificationLinks.Cast<object>()); } OpenCollection(owner, "REQUIREMENT VERIFICATION CROSSWALK · " + d.Title, rows, "Requirement descent retains evidence and verification references."); }); }

        private static void HadalDescent(Window owner)
        {
            WithVersion(owner, delegate(LivingDocument d, LivingVersion v) { LivingParagraph p = Choose<LivingParagraph>(owner, "Choose paragraph for hadal descent", v.Paragraphs); if (p == null) return; List<object> rows = new List<object> { d, v, p }; HashSet<string> claims = new HashSet<string>(p.ClaimIds, StringComparer.Ordinal); rows.AddRange(v.Claims.Where(x => claims.Contains(x.Id)).Cast<object>()); HashSet<string> evidence = new HashSet<string>(p.EvidenceIds.Concat(v.Claims.Where(x => claims.Contains(x.Id)).SelectMany(x => x.EvidenceIds)), StringComparer.Ordinal); rows.AddRange(v.Evidence.Where(x => evidence.Contains(x.Id)).Cast<object>()); HashSet<string> calcs = new HashSet<string>(p.CalculationIds.Concat(v.Claims.Where(x => claims.Contains(x.Id)).SelectMany(x => x.CalculationIds)), StringComparer.Ordinal); rows.AddRange(v.Calculations.Where(x => calcs.Contains(x.Id)).Cast<object>()); HashSet<string> models = new HashSet<string>(p.ModelIds.Concat(v.Claims.Where(x => claims.Contains(x.Id)).SelectMany(x => x.ModelIds)), StringComparer.Ordinal); rows.AddRange(v.Models.Where(x => models.Contains(x.Id)).Cast<object>()); HashSet<string> objs = new HashSet<string>(p.ObjectionIds.Concat(v.Claims.Where(x => claims.Contains(x.Id)).SelectMany(x => x.ObjectionIds)), StringComparer.Ordinal); rows.AddRange(v.Objections.Where(x => objs.Contains(x.Id)).Cast<object>()); rows.AddRange(LivingDocumentKernel.ParagraphGenealogy(d, p.Id).Cast<object>()); OpenCollection(owner, "HADAL DOCUMENT DESCENT · " + p.Heading, rows, "Paragraph → claim → evidence/calculation/model/objection → version genealogy."); });
        }

