        private static void SeedStarter(DeepSystemsContext ctx) { LivingDocument d = LivingDocumentKernel.Starter("Atlas Intelligence Dossier", "RESEARCH_DOSSIER"); Store.Documents.Add(d); Save(ctx); LivingVersion v = LivingDocumentKernel.Current(d); AppendLedger(ctx, "GENESIS", d.Id, "DOCΩ starter living dossier", v == null ? "" : v.RootFingerprint, ""); }
        private static LivingDocument ChooseDocument(Window owner) { EnsureLoaded(); return Store.Documents.Count == 0 ? null : Choose<LivingDocument>(owner, "Choose living document", Store.Documents); }
        private static void WithVersion(Window owner, Action<LivingDocument,LivingVersion> action) { LivingDocument d = ChooseDocument(owner); if (d == null) return; LivingVersion v = LivingDocumentKernel.Current(d); if (v != null) action(d, v); }

        private static LivingVersion CloneVersion(LivingDocument d, LivingVersion source, string note, string branch)
        {
            LivingVersion v = Json.Deserialize<LivingVersion>(Json.Serialize(source)); v.Id = LivingDocumentKernel.NewId("VER"); v.DocumentId = d.Id; v.Number = d.Versions.Count == 0 ? 1 : d.Versions.Max(x => x.Number) + 1; v.ParentVersionId = source.Id; v.Branch = String.IsNullOrWhiteSpace(branch) ? source.Branch : branch; v.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); v.ChangeNote = note; v.Frozen = false; v.RootFingerprint = LivingDocumentKernel.Fingerprint(v); return v;
        }
        private static void CommitVersion(LivingDocument d, LivingVersion v) { v.RootFingerprint = LivingDocumentKernel.Fingerprint(v); d.Versions.Add(v); while (d.Versions.Count > MaxVersionsPerDocument) d.Versions.RemoveAt(0); d.CurrentVersionId = v.Id; d.ActiveBranch = v.Branch; }

        private static void Ensure(DeepSystemsContext ctx) { lock (Gate) { string root = ctx.DataRoot ?? ""; if (Store != null && String.Equals(LoadedRoot, root, StringComparison.OrdinalIgnoreCase)) return; LoadedRoot = root; Store = Load(ctx); } }
        private static void EnsureLoaded() { if (Store == null) Store = new LivingDocumentStore(); }
        private static string StorePath(DeepSystemsContext ctx) { string d = Path.Combine(ctx.DataRoot, "deep-systems"); Directory.CreateDirectory(d); return Path.Combine(d, "controller-living-document-factory.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { string d = Path.Combine(ctx.DataRoot, "deep-systems"); Directory.CreateDirectory(d); return Path.Combine(d, "controller-living-document-ledger.jsonl"); }
        private static LivingDocumentStore Load(DeepSystemsContext ctx) { string p = StorePath(ctx), prev = p + ".previous"; foreach (string q in new[] { p, prev }) { if (!File.Exists(q)) continue; try { LivingDocumentStore s = Json.Deserialize<LivingDocumentStore>(File.ReadAllText(q, Encoding.UTF8)); if (s != null && s.Schema <= 1) { Normalize(s); return s; } } catch { try { File.Copy(q, q + ".corrupt-" + DateTime.UtcNow.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture), true); } catch { } } } return new LivingDocumentStore(); }
        private static void Normalize(LivingDocumentStore s) { if (s.Documents == null) s.Documents = new List<LivingDocument>(); if (s.Projections == null) s.Projections = new List<LivingProjectionReceipt>(); if (s.Impacts == null) s.Impacts = new List<LivingImpactReport>(); if (s.Baselines == null) s.Baselines = new List<LivingBaseline>(); if (s.Seals == null) s.Seals = new List<LivingPublicationSeal>(); foreach (LivingDocument d in s.Documents) { if (d.Versions == null) d.Versions = new List<LivingVersion>(); foreach (LivingVersion v in d.Versions) NormalizeVersion(v); } }
        private static void NormalizeVersion(LivingVersion v) { if (v.Sections == null) v.Sections = new List<LivingSection>(); if (v.Paragraphs == null) v.Paragraphs = new List<LivingParagraph>(); if (v.Claims == null) v.Claims = new List<LivingClaim>(); if (v.Evidence == null) v.Evidence = new List<LivingEvidenceAnchor>(); if (v.Calculations == null) v.Calculations = new List<LivingCalculation>(); if (v.Models == null) v.Models = new List<LivingModelBinding>(); if (v.Assumptions == null) v.Assumptions = new List<LivingAssumption>(); if (v.Objections == null) v.Objections = new List<LivingObjection>(); if (v.Decisions == null) v.Decisions = new List<LivingDecisionRecord>(); if (v.Requirements == null) v.Requirements = new List<LivingRequirement>(); if (v.Definitions == null) v.Definitions = new List<LivingDefinition>(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { Normalize(Store); Store.Revision++; Store.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); Trim(Store.Documents, MaxDocuments); string p = StorePath(ctx), next = p + ".next", prev = p + ".previous"; File.WriteAllText(next, Json.Serialize(Store), new UTF8Encoding(false)); if (File.Exists(p)) { try { File.Copy(p, prev, true); } catch { } } if (File.Exists(p)) File.Delete(p); File.Move(next, p); } }
        private static void Trim<T>(List<T> xs, int n) { if (xs == null) return; while (xs.Count > n) xs.RemoveAt(xs.Count - 1); }

        private static void AppendLedger(DeepSystemsContext ctx, string ev, string subject, string detail, string versionFp, string cert)
        {
            lock (Gate) { List<LivingLedgerRecord> old = ReadLedger(ctx); long seq = old.Count == 0 ? 1 : old[old.Count - 1].Sequence + 1; string prev = old.Count == 0 ? new string('0', 64) : old[old.Count - 1].EntryHash; LivingLedgerRecord r = new LivingLedgerRecord { Schema = 1, Sequence = seq, Utc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture), Event = ev, Subject = subject, Detail = detail, VersionFingerprint = versionFp, CertificateHash = cert, PrevHash = prev }; r.EntryHash = LivingDocumentKernel.HashText(r.Schema + "|" + r.Sequence + "|" + r.Utc + "|" + r.Event + "|" + r.Subject + "|" + r.Detail + "|" + r.VersionFingerprint + "|" + r.CertificateHash + "|" + r.PrevHash); File.AppendAllText(LedgerPath(ctx), Json.Serialize(r) + Environment.NewLine, new UTF8Encoding(false)); }
        }
        private static List<LivingLedgerRecord> ReadLedger(DeepSystemsContext ctx) { List<LivingLedgerRecord> r = new List<LivingLedgerRecord>(); string p = LedgerPath(ctx); if (!File.Exists(p)) return r; Queue<string> q = new Queue<string>(); foreach (string line in File.ReadLines(p)) { q.Enqueue(line); if (q.Count > MaxLedgerRead) q.Dequeue(); } foreach (string line in q) { if (String.IsNullOrWhiteSpace(line)) continue; try { LivingLedgerRecord x = Json.Deserialize<LivingLedgerRecord>(line); if (x != null) r.Add(x); } catch { } } return r; }
        private static bool VerifyLedger(List<LivingLedgerRecord> xs) { if (xs == null || xs.Count == 0) return true; for (int i = 0; i < xs.Count; i++) { LivingLedgerRecord r = xs[i]; if (i > 0 && !String.Equals(r.PrevHash, xs[i - 1].EntryHash, StringComparison.OrdinalIgnoreCase)) return false; string h = LivingDocumentKernel.HashText(r.Schema + "|" + r.Sequence + "|" + r.Utc + "|" + r.Event + "|" + r.Subject + "|" + r.Detail + "|" + r.VersionFingerprint + "|" + r.CertificateHash + "|" + r.PrevHash); if (!String.Equals(h, r.EntryHash, StringComparison.OrdinalIgnoreCase)) return false; } return true; }

        private static string HashObject(object source) { try { return LivingDocumentKernel.HashText(Json.Serialize(source)); } catch { return LivingDocumentKernel.HashText(source == null ? "" : source.ToString()); } }
        private static string ReadId(object source) { if (source == null) return "UNKNOWN"; try { PropertyInfo p = source.GetType().GetProperty("Id", BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase); object v = p == null ? null : p.GetValue(source, null); return v == null ? source.GetType().Name : Convert.ToString(v, CultureInfo.InvariantCulture); } catch { return source.GetType().Name; } }
        private static string SafeName(string s) { if (String.IsNullOrWhiteSpace(s)) return "document"; StringBuilder b = new StringBuilder(); foreach (char c in s) b.Append(Char.IsLetterOrDigit(c) ? c : '-'); string x = b.ToString().Trim('-'); while (x.Contains("--")) x = x.Replace("--", "-"); return x.Length > 80 ? x.Substring(0, 80) : x; }

        private static T Choose<T>(Window owner, string title, IList<T> items) where T : class { Window w = W(owner, "YOMI · " + title.ToUpperInvariant(), 1000, 700); DockPanel root = Shell(title.ToUpperInvariant(), "Double-click to select."); ListBox list = List(); list.ItemsSource = items; T selected = null; list.MouseDoubleClick += delegate { selected = list.SelectedItem as T; w.DialogResult = selected != null; w.Close(); }; root.Children.Add(list); w.Content = root; bool? r = w.ShowDialog(); return r == true ? selected : null; }
        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, Background = Bg, Foreground = Text, WindowStartupLocation = owner == null ? WindowStartupLocation.CenterScreen : WindowStartupLocation.CenterOwner, Owner = owner }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Background = Bg }; StackPanel head = new StackPanel { Margin = new Thickness(20, 18, 20, 10) }; head.Children.Add(new TextBlock { Text = title, Foreground = Text, FontSize = 25, FontWeight = FontWeights.Bold }); head.Children.Add(new TextBlock { Text = subtitle ?? "", Foreground = Muted, FontSize = 13, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 5, 0, 0) }); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static void Portal(WrapPanel panel, string badge, string title, string detail, RoutedEventHandler click) { Button b = new Button { Width = 285, MinHeight = 118, Margin = new Thickness(7), Padding = new Thickness(14), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel p = new StackPanel(); p.Children.Add(new TextBlock { Text = badge + "   " + title, Foreground = Accent, FontWeight = FontWeights.Bold, FontSize = 13, TextWrapping = TextWrapping.Wrap }); p.Children.Add(new TextBlock { Text = detail, Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 7, 0, 0) }); b.Content = p; b.Click += click; panel.Children.Add(b); }
        private static void SmallPortal(Panel p, string title, RoutedEventHandler click) { Button b = new Button { Content = title, Margin = new Thickness(5), Padding = new Thickness(11, 7, 11, 7), Background = Raised, Foreground = Accent, BorderBrush = Border }; b.Click += click; p.Children.Add(b); }
        private static ListBox List() { return new ListBox { Margin = new Thickness(18), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), FontFamily = new FontFamily("Consolas"), FontSize = 12 }; }
        private static void OpenCollection(Window owner, string title, IList<object> items, string note) { Window w = W(owner, "YOMI · " + title, 1360, 840); DockPanel root = Shell(title, note + "   ·   " + (items == null ? 0 : items.Count) + " retained rows"); ListBox list = List(); list.ItemsSource = items ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
        private static void TextView(Window owner, string title, string text) { Window w = W(owner, "YOMI · " + title, 1360, 860); DockPanel root = Shell(title, "Read-only canonical text view."); TextBox box = new TextBox { Text = text ?? "", Margin = new Thickness(18), Background = Surface, Foreground = Text, BorderBrush = Border, FontFamily = new FontFamily("Consolas"), FontSize = 13, IsReadOnly = true, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto }; root.Children.Add(box); w.Content = root; w.Show(); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 760, 300); DockPanel root = Shell(title, label); TextBox box = new TextBox { Text = initial ?? "", Margin = new Thickness(20, 6, 20, 10), Padding = new Thickness(8), Background = Surface, Foreground = Text, BorderBrush = Border, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, MinHeight = 80, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; DockPanel.SetDock(box, Dock.Top); root.Children.Add(box); StackPanel buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(20) }; Button ok = new Button { Content = "COMMIT", Padding = new Thickness(18, 7, 18, 7), Margin = new Thickness(6), Background = Raised, Foreground = Green, BorderBrush = Border }; Button cancel = new Button { Content = "CANCEL", Padding = new Thickness(18, 7, 18, 7), Margin = new Thickness(6), Background = Raised, Foreground = Muted, BorderBrush = Border }; string value = null; ok.Click += delegate { value = box.Text; w.DialogResult = true; w.Close(); }; cancel.Click += delegate { w.DialogResult = false; w.Close(); }; buttons.Children.Add(cancel); buttons.Children.Add(ok); root.Children.Add(buttons); w.Content = root; bool? r = w.ShowDialog(); return r == true ? value : null; }
        private static Brush B(string hex) { return (Brush)new BrushConverter().ConvertFromString(hex); }
    }
